import { describe, it, expect, beforeEach, afterEach } from "vitest";
import {
  kspec,
  kspecJson,
  setupTempFixtures,
  cleanupTempDir,
} from "../helpers/cli";

interface InboxSummary {
  ref: string;
  text: string;
