   470→  for (const task of completedTasks) {
   471→    taskByRef.set(task.ref, task);
   472→  }
   473→
   474→  // Track which tasks have been linked to a commit (for dedup)
   475→  const linkedTaskRefs = new Set<string>();
   476→
   477→  for (const commit of commits) {
   478→    if (commit.task_refs.length > 0) {
   479→      let linkedTask: CompletedTaskSummary | undefined;
   480→      for (const trailerRef of commit.task_refs) {
   481→        // Resolve the trailer ref (slug or ULID) to the short ULID ref
   482→        const resolvedRef = taskRefResolver.get(trailerRef);
   483→        if (resolvedRef) {
   484→          linkedTask = taskByRef.get(resolvedRef);
   485→        }
   486→        // Also try direct match on short ULID ref
   487→        if (!linkedTask) {
   488→          linkedTask = taskByRef.get(trailerRef);
   489→        }
   490→        if (linkedTask) {
   491→          linkedTaskRefs.add(linkedTask.ref);
   492→          // Use the later of commit date and task completion date for sort accuracy
   493→          const commitTime = new Date(commit.date).getTime();
   494→          const taskTime = new Date(linkedTask.completed_at).getTime();
   495→          const laterDate =
   496→            taskTime > commitTime ? linkedTask.completed_at : commit.date;
   497→          items.push({
   498→            type: "linked_commit",
   499→            date: laterDate,
   500→            commit,
   501→            task: linkedTask,
   502→          });
   503→          break; // One linked entry per commit
   504→        }
   505→      }
   506→      if (!linkedTask) {
   507→        // Task ref in trailer but no matching completed task found
   508→        items.push({ type: "commit", date: commit.date, commit });
   509→      }
   510→    } else {
   511→      items.push({ type: "commit", date: commit.date, commit });
   512→    }
   513→  }
   514→
   515→  // Add task completions not already linked to a commit
   516→  for (const task of completedTasks) {
   517→    if (!linkedTaskRefs.has(task.ref)) {
   518→      items.push({
   519→        type: "task_completion",
   520→        date: task.completed_at,
   521→        task,
   522→      });
   523→    }
   524→  }
   525→
   526→  // AC: @session-start-activity-timeline ac-activity-sort
   527→  // Sort most recent first
   528→  items.sort(
   529→    (a, b) => new Date(b.date).getTime() - new Date(a.date).getTime(),
   530→  );
   531→
   532→  return items;
   533→}
