841→/**
842→ * Perform session checkpoint - check for uncommitted work before ending session.
843→ *
844→ * This is designed for use as a Claude Code stop hook. It checks for:
845→ * - Uncommitted git changes (staged, unstaged, untracked)
846→ * - Tasks in in_progress status
847→ * - Incomplete todos on active tasks
848→ *
849→ * Returns a structured result indicating whether the session can end cleanly.
850→ */
851→export async function performCheckpoint(
852→  ctx: KspecContext,
853→  options: CheckpointOptions,
854→): Promise<CheckpointResult> {
855→  const issues: CheckpointIssue[] = [];
856→  const instructions: string[] = [];
857→
858→  // Load tasks
859→  const allTasks = await loadAllTasks(ctx);
860→
861→  // Check for in-progress tasks
862→  const inProgressTasks = allTasks.filter((t) => t.status === "in_progress");
863→  for (const task of inProgressTasks) {
864→    const ref = task.slugs[0]
865→      ? `@${task.slugs[0]}`
866→      : `@${task._ulid.slice(0, 8)}`;
867→    issues.push({
868→      type: "in_progress_task",
869→      description: `Task ${ref} is still in progress: ${task.title}`,
870→      details: {
871→        ref,
872→        title: task.title,
873→        started_at: task.started_at,
874→      },
875→    });
876→
877→    // Check for incomplete todos on this task
878→    const incompleteTodos = task.todos.filter((t) => !t.done);
879→    for (const todo of incompleteTodos) {
880→      issues.push({
881→        type: "incomplete_todo",
882→        description: `Incomplete todo on ${ref}: ${todo.text}`,
883→        details: {
884→          task_ref: ref,
885→          todo_id: todo.id,
886→          text: todo.text,
887→        },
888→      });
889→    }
890→  }
891→
892→  // Check for uncommitted git changes
893→  if (isGitRepo(ctx.rootDir)) {
894→    const workingTree = getWorkingTreeStatus(ctx.rootDir);
895→    if (!workingTree.clean) {
896→      const changeCount =
897→        workingTree.staged.length +
898→        workingTree.unstaged.length +
899→        workingTree.untracked.length;
900→
901→      issues.push({
902→        type: "uncommitted_changes",
903→        description: `${changeCount} uncommitted changes in working tree`,
904→        details: {
905→          staged: workingTree.staged.length,
906→          unstaged: workingTree.unstaged.length,
907→          untracked: workingTree.untracked.length,
908→        },
909→      });
910→    }
911→  }
912→
913→  // Build instructions based on issues
914→  if (issues.length > 0 && !options.force) {
915→    instructions.push(
916→      "If you've been instructed to ignore this message or are working on",
917→    );
918→    instructions.push(
919→      "unrelated things to any in progress tasks then disregard this message,",
920→    );
921→    instructions.push("otherwise before ending this session, please:");
922→
923→    const hasInProgress = issues.some((i) => i.type === "in_progress_task");
924→    const hasUncommitted = issues.some((i) => i.type === "uncommitted_changes");
925→    const hasIncompleteTodos = issues.some((i) => i.type === "incomplete_todo");
926→
927→    let step = 1;
928→
929→    if (hasInProgress) {
930→      instructions.push(
931→        `${step++}. Read in-progress task notes to get full context of the current task status`,
932→      );
933→      instructions.push(
934→        `${step++}. Add notes documenting current state if any context is missing from this session`,
935→      );
936→      instructions.push(
937→        `${step++}. Complete the task if you've completed the objectives and no AC are left uncovered\notherwise leave it in progress for a future session`,
938→      );
939→    }
940→
941→    if (hasIncompleteTodos) {
942→      instructions.push(
943→        `${step++}. Complete or acknowledge incomplete todos on active tasks`,
944→      );
945→    }
946→
947→    if (hasUncommitted) {
948→      instructions.push(
949→        `${step++}. Commit your changes with a descriptive message`,
950→      );
951→
952→      // Add WIP commit guidance if there are in-progress tasks
953→      if (inProgressTasks.length > 0) {
954→        const task = inProgressTasks[0];
955→        const guidance = formatCommitGuidance(task, { wip: true });
956→        instructions.push("");
957→        instructions.push("Suggested WIP commit:");
958→        instructions.push(`  ${guidance.message}`);
959→        instructions.push("");
960→        for (const trailer of guidance.trailers) {
961→          instructions.push(`  ${trailer}`);
962→        }
963→      }
964→    }
965→
966→    instructions.push("");
967→    instructions.push("Use: kspec task @task to get current task state");
968→    instructions.push(
969→      'Use: kspec task note @task "Progress notes..." to document state',
970→    );
971→    instructions.push(
972→      'Use: kspec task complete @task --reason "Summary" if task is done',
973→    );
974→  }
975→
976→  // Allow stop if:
977→  // - No issues found
978→  // - --force flag passed
979→  // - This is a retry (stop_hook_active = true from previous block)
980→  const isRetry = options.stopHookActive === true;
981→  const ok = issues.length === 0 || options.force === true || isRetry;
982→
983→  let message: string;
984→  if (isRetry && issues.length > 0) {
985→    message = `[kspec] Session checkpoint: ${issues.length} issue(s) acknowledged - allowing stop`;
986→  } else if (ok) {
987→    message = "[kspec] Session checkpoint passed - ready to end session";
988→  } else {
989→    message = `[kspec] Session checkpoint: ${issues.length} issue(s) need attention`;
990→  }
991→
992→  return {
993→    ok,
994→    message,
995→    issues,
996→    instructions,
997→  };
998→}
