export interface NoteSummary {
  task_ref: string;
  task_title: string;
  task_status: "in_progress" | "pending_review" | "needs_work" | "completed";
  note_ulid: string;
  created_at: string;
  author: string | null;
  content: string;
}

export interface TodoSummary {
  task_ref: string;
  task_title: string;
  id: number;
  text: string;
  added_at: string;
  added_by: string | null;
}

export interface ReadyTaskSummary {
  ref: string;
  slug: string | null;
  title: string;
  description: string | null;
  priority: number;
  spec_ref: string | null;
  tags: string[];
  unlocks: number;
}

export interface BlockedTaskSummary {
  ref: string;
  slug: string | null;
  title: string;
  description: string | null;
  blocked_by: string[];
