export interface ActiveTaskSummary {
  ref: string;
  slug: string | null;
  title: string;
  description: string | null;
  status: "in_progress" | "needs_work" | "pending_review";
  started_at: string | null;
  priority: number;
  spec_ref: string | null;
  note_count: number;
  last_note_at: string | null;
  todo_count: number;
  incomplete_todos: number;
}

export interface NoteSummary {
  task_ref: string;
  task_title: string;
  task_status: "in_progress" | "pending_review" | "needs_work" | "completed";
  note_ulid: string;
  created_at: string;
  author: string | null;
  content: string;
}

export interface TodoSummary {
  task_ref: string;
  task_title: string;
  id: number;
  text: string;
  added_at: string;
  added_by: string | null;
}

export interface ReadyTaskSummary {
  ref: string;
  slug: string | null;
  title: string;
  description: string | null;
  priority: number;
  spec_ref: string | null;
  tags: string[];
  unlocks: number;
}

export interface BlockedTaskSummary {
  ref: string;
  slug: string | null;
  title: string;
  description: string | null;
  blocked_by: string[];
  unmet_deps: string[];
  unlocks: number;
}

export interface CompletedTaskSummary {
  ref: string;
  slug: string | null;
  title: string;
