}

export interface BlockedTaskSummary {
  ref: string;
  slug: string | null;
  title: string;
  description: string | null;
  blocked_by: string[];
  unmet_deps: string[];
  unlocks: number;
}

export interface CompletedTaskSummary {
  ref: string;
  slug: string | null;
  title: string;
  completed_at: string;
  closed_reason: string | null;
  origin?: "manual" | "derived" | "observation_promotion";
}

export interface CommitSummary {
  hash: string;
  full_hash: string;
  date: string;
  message: string;
  author: string;
  task_refs: string[];
}

/**
 * A single entry in the unified activity timeline.
 * Merges completed tasks and git commits into a chronological view.
 * Commits linked to tasks via Task: @slug trailer are deduplicated into combined entries.
 */
export type ActivityItem =
  | { type: "task_completion"; date: string; task: CompletedTaskSummary }
  | { type: "commit"; date: string; commit: CommitSummary }
  | {
      type: "linked_commit";
      date: string;
      commit: CommitSummary;
      task: CompletedTaskSummary;
    };

export interface SessionStats {
  total_tasks: number;
  in_progress: number;
  needs_work: number;
  pending_review: number;
  ready: number;
  blocked: number;
  completed: number;
  inbox_items: number;
}

/**
 * Computed/derived fields for JSON consumers.
 * Aggregates data from other session context fields into a single
 * convenient object. Raw source arrays are preserved unchanged.
 */
export interface SessionContextComputed {
  /** Count of inbox items with no triage record */
  inbox_untriaged_count: number;
  /** Count of inbox items triaged with 'defer' action */
  inbox_deferred_count: number;
  /** Total inbox item count */
  inbox_total: number;
  /** Map of task ref (short ULID) to count of pending tasks it unblocks */
  task_unlocks: Record<string, number>;
  /** Unified activity timeline (same as activity_timeline, for computed namespace) */
  recent_activity: ActivityItem[];
}

export interface InboxSummary {
  ref: string;
  text: string;
  created_at: string;
  tags: string[];
  added_by: string | null;
  triaged: boolean;
  triage_action: string | null;
}

export interface InboxStats {
  total: number;
  untriaged: number;
  deferred: number;
  triaged: number;
}

export interface ObservationSummary {
  ref: string;
  type: ObservationType;
  content: string;
  created_at: string;
  author: string | null;
  resolved: boolean;
  workflow_ref: string | null;
}

export interface SessionOptions {
  brief?: boolean;
  full?: boolean;
  since?: string;
  git?: boolean;
  limit?: string;
  eligible?: boolean; // Only include automation-eligible tasks in ready_tasks
}

// ─── Data Gathering ──────────────────────────────────────────────────────────

/**
 * Build a reverse dependency map: for each task ULID, count how many
 * pending tasks depend on it. Unresolvable refs are silently skipped.
 */
function computeUnlocksMap(
  allTasks: LoadedTask[],
  index: ReferenceIndex,
): Map<string, number> {
  const counts = new Map<string, number>();

  for (const task of allTasks) {
    // Only count pending tasks as "unlockable" downstream work per spec
    if (task.status !== "pending") continue;

    for (const depRef of task.depends_on) {
      const result = index.resolve(depRef);
      if (!result.ok) continue; // AC: unresolvable refs silently skipped
      const depUlid = result.item._ulid;
      counts.set(depUlid, (counts.get(depUlid) || 0) + 1);
    }
  }

  return counts;
}

function toActiveTaskSummary(
  task: LoadedTask,
  index: ReferenceIndex,
): ActiveTaskSummary {
  const lastNote =
    task.notes.length > 0 ? task.notes[task.notes.length - 1] : null;
  const incompleteTodos = task.todos.filter((t) => !t.done).length;
  return {
    ref: index.shortUlid(task._ulid),
    slug: task.slugs.length > 0 ? task.slugs[0] : null,
    title: task.title,
    description: task.description || null,
    status: task.status as "in_progress" | "needs_work" | "pending_review",
    started_at: task.started_at || null,
    priority: task.priority,
    spec_ref: task.spec_ref || null,
    note_count: task.notes.length,
    last_note_at: lastNote ? lastNote.created_at : null,
    todo_count: task.todos.length,
    incomplete_todos: incompleteTodos,
  };
}

function toReadyTaskSummary(
  task: LoadedTask,
  index: ReferenceIndex,
  unlocksMap: Map<string, number>,
): ReadyTaskSummary {
  return {
    ref: index.shortUlid(task._ulid),
    slug: task.slugs.length > 0 ? task.slugs[0] : null,
    title: task.title,
    description: task.description || null,
    priority: task.priority,
    spec_ref: task.spec_ref || null,
    tags: task.tags,
    unlocks: unlocksMap.get(task._ulid) || 0,
  };
}

function toBlockedTaskSummary(
  task: LoadedTask,
  _allTasks: LoadedTask[],
  index: ReferenceIndex,
  unlocksMap: Map<string, number>,
): BlockedTaskSummary {
  // Find unmet dependencies
  const unmetDeps: string[] = [];
  for (const depRef of task.depends_on) {
    const result = index.resolve(depRef);
    if (result.ok) {
      const depItem = result.item;
      if ("status" in depItem && depItem.status !== "completed") {
        unmetDeps.push(depRef);
      }
    }
  }

  return {
    ref: index.shortUlid(task._ulid),
    slug: task.slugs.length > 0 ? task.slugs[0] : null,
    title: task.title,
    description: task.description || null,
    blocked_by: task.blocked_by,
    unmet_deps: unmetDeps,
    unlocks: unlocksMap.get(task._ulid) || 0,
  };
}

function toCompletedTaskSummary(
  task: LoadedTask,
  index: ReferenceIndex,
): CompletedTaskSummary {
  return {
    ref: index.shortUlid(task._ulid),
    slug: task.slugs.length > 0 ? task.slugs[0] : null,
    title: task.title,
    completed_at: task.completed_at || "",
    closed_reason: task.closed_reason || null,
    origin: task.origin,
  };
}

function collectRecentNotes(
  tasks: LoadedTask[],
  index: ReferenceIndex,
  options: { limit: number; since: Date | null },
): NoteSummary[] {
  const allNotes: NoteSummary[] = [];

  for (const task of tasks) {
    // Only include notes from in_progress, pending_review, or completed tasks
    const taskStatus = task.status as "in_progress" | "pending_review" | "needs_work" | "completed";
    if (!["in_progress", "pending_review", "needs_work", "completed"].includes(taskStatus)) {
      continue;
    }

    for (const note of task.notes) {
      const noteDate = new Date(note.created_at);

      // Filter by since date if provided
      if (options.since && noteDate < options.since) {
        continue;
      }

      // Filter out superseded notes
      if (isNoteSuperseded(note, task.notes)) {
        continue;
      }

      allNotes.push({
        task_ref: index.shortUlid(task._ulid),
        task_title: task.title,
        task_status: taskStatus,
        note_ulid: note._ulid.slice(0, 8),
        created_at: note.created_at,
        author: note.author || null,
        content: note.content,
      });
    }
  }

  // Sort by date descending, take limit
  return allNotes
    .sort(
      (a, b) =>
        new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
    )
    .slice(0, options.limit);
}

function collectIncompleteTodos(
  tasks: LoadedTask[],
  index: ReferenceIndex,
  options: { limit: number },
): TodoSummary[] {
  const allTodos: TodoSummary[] = [];

  for (const task of tasks) {
    for (const todo of task.todos) {
      // Only include incomplete todos
      if (todo.done) continue;

      allTodos.push({
        task_ref: index.shortUlid(task._ulid),
        task_title: task.title,
        id: todo.id,
        text: todo.text,
        added_at: todo.added_at,
        added_by: todo.added_by || null,
      });
    }
  }

  // Sort by added_at descending (most recent first), take limit
  return allTodos
    .sort(
      (a, b) => new Date(b.added_at).getTime() - new Date(a.added_at).getTime(),
    )
    .slice(0, options.limit);
}

