257→ * Computed/derived fields for JSON consumers.
258→ * Aggregates data from other session context fields into a single
259→ * convenient object. Raw source arrays are preserved unchanged.
260→ */
261→export interface SessionContextComputed {
262→  /** Count of inbox items with no triage record */
263→  inbox_untriaged_count: number;
264→  /** Count of inbox items triaged with 'defer' action */
265→  inbox_deferred_count: number;
266→  /** Total inbox item count */
267→  inbox_total: number;
268→  /** Map of task ref (short ULID) to count of pending tasks it unblocks */
269→  task_unlocks: Record<string, number>;
270→  /** Unified activity timeline (same as activity_timeline, for computed namespace) */
271→  recent_activity: ActivityItem[];
272→}
273→
274→export interface InboxSummary {
275→  ref: string;
276→  text: string;
277→  created_at: string;
278→  tags: string[];
279→  added_by: string | null;
280→  triaged: boolean;
281→  triage_action: string | null;
282→}
283→
284→export interface InboxStats {
285→  total: number;
286→  untriaged: number;
287→  deferred: number;
288→  triaged: number;
289→}
290→
291→export interface ObservationSummary {
292→  ref: string;
293→  type: ObservationType;
294→  content: string;
295→  created_at: string;
296→  author: string | null;
297→  resolved: boolean;
298→  workflow_ref: string | null;
299→}
300→
301→export interface SessionOptions {
302→  brief?: boolean;
303→  full?: boolean;
304→  since?: string;
305→  git?: boolean;
306→  limit?: string;
307→  eligible?: boolean; // Only include automation-eligible tasks in ready_tasks
308→}
309→
310→// ─── Data Gathering ──────────────────────────────────────────────────────────
311→
312→/**
313→ * Build a reverse dependency map: for each task ULID, count how many
314→ * pending tasks depend on it. Unresolvable refs are silently skipped.
315→ */
316→function computeUnlocksMap(
317→  allTasks: LoadedTask[],
318→  index: ReferenceIndex,
319→): Map<string, number> {
320→  const counts = new Map<string, number>();
321→
322→  for (const task of allTasks) {
323→    // Only count pending tasks as "unlockable" downstream work per spec
324→    if (task.status !== "pending") continue;
325→
326→    for (const depRef of task.depends_on) {
327→      const result = index.resolve(depRef);
328→      if (!result.ok) continue; // AC: unresolvable refs silently skipped
329→      const depUlid = result.item._ulid;
330→      counts.set(depUlid, (counts.get(depUlid) || 0) + 1);
331→    }
332→  }
333→
334→  return counts;
335→}
336→
337→function toActiveTaskSummary(
338→  task: LoadedTask,
339→  index: ReferenceIndex,
340→): ActiveTaskSummary {
341→  const lastNote =
342→    task.notes.length > 0 ? task.notes[task.notes.length - 1] : null;
343→  const incompleteTodos = task.todos.filter((t) => !t.done).length;
344→  return {
345→    ref: index.shortUlid(task._ulid),
346→    slug: task.slugs.length > 0 ? task.slugs[0] : null,
347→    title: task.title,
348→    description: task.description || null,
349→    status: task.status as "in_progress" | "needs_work" | "pending_review",
350→    started_at: task.started_at || null,
351→    priority: task.priority,
352→    spec_ref: task.spec_ref || null,
353→    note_count: task.notes.length,
354→    last_note_at: lastNote ? lastNote.created_at : null,
355→    todo_count: task.todos.length,
356→    incomplete_todos: incompleteTodos,
357→  };
358→}
359→
360→function toReadyTaskSummary(
361→  task: LoadedTask,
362→  index: ReferenceIndex,
363→  unlocksMap: Map<string, number>,
364→): ReadyTaskSummary {
365→  return {
366→    ref: index.shortUlid(task._ulid),
367→    slug: task.slugs.length > 0 ? task.slugs[0] : null,
368→    title: task.title,
369→    description: task.description || null,
370→    priority: task.priority,
371→    spec_ref: task.spec_ref || null,
372→    tags: task.tags,
373→    unlocks: unlocksMap.get(task._ulid) || 0,
374→  };
375→}
376→
377→function toBlockedTaskSummary(
378→  task: LoadedTask,
379→  _allTasks: LoadedTask[],
380→  index: ReferenceIndex,
381→  unlocksMap: Map<string, number>,
382→): BlockedTaskSummary {
383→  // Find unmet dependencies
384→  const unmetDeps: string[] = [];
385→  for (const depRef of task.depends_on) {
386→    const result = index.resolve(depRef);
387→    if (result.ok) {
388→      const depItem = result.item;
389→      if ("status" in depItem && depItem.status !== "completed") {
390→        unmetDeps.push(depRef);
391→      }
392→    }
393→  }
394→
395→  return {
396→    ref: index.shortUlid(task._ulid),
397→    slug: task.slugs.length > 0 ? task.slugs[0] : null,
398→    title: task.title,
399→    description: task.description || null,
400→    blocked_by: task.blocked_by,
401→    unmet_deps: unmetDeps,
402→    unlocks: unlocksMap.get(task._ulid) || 0,
403→  };
404→}
405→
406→function toCompletedTaskSummary(
407→  task: LoadedTask,
408→  index: ReferenceIndex,
409→): CompletedTaskSummary {
410→  return {
411→    ref: index.shortUlid(task._ulid),
412→    slug: task.slugs.length > 0 ? task.slugs[0] : null,
413→    title: task.title,
414→    completed_at: task.completed_at || "",
415→    closed_reason: task.closed_reason || null,
416→    origin: task.origin,
417→  };
418→}
419→
420→function collectRecentNotes(
421→  tasks: LoadedTask[],
422→  index: ReferenceIndex,
423→  options: { limit: number; since: Date | null },
424→): NoteSummary[] {
425→  const allNotes: NoteSummary[] = [];
426→
427→  for (const task of tasks) {
428→    // Only include notes from in_progress, pending_review, or completed tasks
429→    const taskStatus = task.status as "in_progress" | "pending_review" | "needs_work" | "completed";
430→    if (!["in_progress", "pending_review", "needs_work", "completed"].includes(taskStatus)) {
431→      continue;
432→    }
433→
434→    for (const note of task.notes) {
435→      const noteDate = new Date(note.created_at);
436→
437→      // Filter by since date if provided
438→      if (options.since && noteDate < options.since) {
439→        continue;
440→      }
441→
442→      // Filter out superseded notes
443→      if (isNoteSuperseded(note, task.notes)) {
444→        continue;
445→      }
446→
447→      allNotes.push({
448→        task_ref: index.shortUlid(task._ulid),
449→        task_title: task.title,
450→        task_status: taskStatus,
451→        note_ulid: note._ulid.slice(0, 8),
452→        created_at: note.created_at,
453→        author: note.author || null,
454→        content: note.content,
455→      });
456→    }
457→  }
458→
459→  // Sort by date descending, take limit
460→  return allNotes
461→    .sort(
462→      (a, b) =>
463→        new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
464→    )
465→    .slice(0, options.limit);
466→}
467→
468→function collectIncompleteTodos(
469→  tasks: LoadedTask[],
470→  index: ReferenceIndex,
471→  options: { limit: number },
472→): TodoSummary[] {
473→  const allTodos: TodoSummary[] = [];
474→
475→  for (const task of tasks) {
476→    for (const todo of task.todos) {
477→      // Only include incomplete todos
478→      if (todo.done) continue;
479→
480→      allTodos.push({
481→        task_ref: index.shortUlid(task._ulid),
482→        task_title: task.title,
483→        id: todo.id,
484→        text: todo.text,
485→        added_at: todo.added_at,
486→        added_by: todo.added_by || null,
487→      });
488→    }
489→  }
490→
491→  // Sort by added_at descending (most recent first), take limit
492→  return allTodos
493→    .sort(
494→      (a, b) => new Date(b.added_at).getTime() - new Date(a.added_at).getTime(),
495→    )
496→    .slice(0, options.limit);
497→}
