import { join } from 'node:path';
import { kspec, kspecJson, setupTempFixtures, cleanupTempDir } from '../helpers/cli';

interface SessionContext {
  recent_notes: Array<{
    task_ref: string;
    task_title: string;
    task_status: 'in_progress' | 'pending_review' | 'completed';
