const signalCleanup = (signal: string) => {
  info(`Received ${signal}, cleaning up...`);
  if (agent) {
    agent.kill();
  }
  // AC: @ralph-session-budget-integration ac-session-close-all-paths
  // Must use async IIFE — signal handlers are called synchronously,
