  // until cleanup completes, then exits explicitly.
  void (async () => {
    try {
      await Promise.all([
        fs.unlink(getSessionBudgetPath(specDir, sessionId)).catch(() => {}),
        closeSession(specDir, sessionId, "abandoned", `Received ${signal}`),
